sys_transform_map.script:
(function transformRow(source, target, map, log, isUpdate) {

    // Add your code here
    target.active = normalizeBoolean(source.getValue('active'));
    target.hidden = normalizeBoolean(source.getValue('hidden'));


    function normalizeBoolean(value) {

        if (value == null || value == '') {
            return false;
        }

        value = value.toString().toLowerCase().trim();

        return value == 'true' ||
            value == '1' ||
            value == 'yes' ||
            value == 'y';
    }

})(source, target, map, log, action === "update");
